    fseek(f, 0, SEEK_SET);

    if ((size_t)sz > sizeof(static_data))
        sz = sizeof(static_data);
    size_t size = fread(static_data, 1, sz, f);
    fclose(f);

    struct config *config;
    struct config_line line;

    config = config_open_for_fuzzing(static_data, size);
    if (!config)
        return 1;

    dump(config, &line, 0);
    config_close(config);
    return 0;
}
